function displayRAGTab(containerEl, plugin) {
  containerEl.createEl("h3", { text: t2("settings.rag.title") });
  const desc = containerEl.createEl("p", {
    text: t2("settings.rag.desc")
  });
  desc.addClass("ia-section-description");
  const tabNavContainer = containerEl.createDiv("ia-rag-tab-nav");
  tabNavContainer.removeClass("ia-hidden");
  const tabContentContainer = containerEl.createDiv("ia-rag-tab-content");
  const subTabs = [
    { id: "overview", label: t2("settings.rag.subTabs.overview"), icon: "\u{1F3E0}" },
    { id: "chunking", label: t2("settings.rag.subTabs.chunking"), icon: "\u{1F4C4}" },
    { id: "search", label: t2("settings.rag.subTabs.search"), icon: "\u{1F50D}" },
    { id: "filters", label: t2("settings.rag.subTabs.filters"), icon: "\u{1F5C2}\uFE0F" },
    { id: "advanced", label: t2("settings.rag.subTabs.advanced"), icon: "\u2699\uFE0F" },
    { id: "websearch", label: t2("settings.rag.subTabs.websearch"), icon: "\u{1F310}" }
  ];
  let activeTab = "overview";
  const renderActiveTab = () => {
    tabContentContainer.empty();
    switch (activeTab) {
      case "overview":
        renderOverviewTab(tabContentContainer, plugin);
        break;
      case "chunking":
        renderChunkingSettings(tabContentContainer, plugin);
        break;
      case "search":
        renderSearchSettings(tabContentContainer, plugin);
        break;
      case "filters":
        renderFileFilters(tabContentContainer, plugin);
        break;
      case "advanced":
        renderAdvancedTab(tabContentContainer, plugin);
        break;
      case "websearch":
        displayWebSearchTab(tabContentContainer, plugin);
        break;
    }
  };
  subTabs.forEach((tab) => {
    const tabBtn = tabNavContainer.createEl("button", {
      text: `${tab.icon} ${tab.label}`,
      cls: "ia-rag-subtab-btn"
    });
    tabBtn.toggleClass("ia-rag-subtab-btn--active", activeTab === tab.id);
    tabBtn.addClass("ia-clickable");
    tabBtn.addEventListener("click", () => {
      activeTab = tab.id;
      tabNavContainer.querySelectorAll(".ia-rag-subtab-btn").forEach((btn, index) => {
        const isActive = subTabs[index].id === activeTab;
        btn.toggleClass("ia-rag-subtab-btn--active", isActive);
      });
      renderActiveTab();
    });
  });
  renderActiveTab();
}
